DO $$ BEGIN CREATE TYPE wsb_automation_trigger AS ENUM ('BOOKING_CONFIRMED','BOOKING_REMINDER','BOOKING_COMPLETED','BIRTHDAY','WINBACK','REVIEW_REQUEST','MANUAL_CAMPAIGN','SURVEY_INVITE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE wsb_automation_job_status AS ENUM ('QUEUED','CLAIMED','DEFERRED','DISPATCHED','SKIPPED','FAILED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE automation_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name text NOT NULL,trigger wsb_automation_trigger NOT NULL,active boolean NOT NULL DEFAULT true,offset_minutes integer NOT NULL DEFAULT 0,config jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE INDEX automation_rules_tenant_trigger_idx ON automation_rules(tenant_id,trigger,active);
CREATE TABLE automation_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,rule_id uuid,trigger wsb_automation_trigger NOT NULL,trigger_key text NOT NULL,window_key text NOT NULL,dedupe_key text NOT NULL,customer_id uuid,booking_id uuid,due_at timestamptz NOT NULL,available_at timestamptz NOT NULL,status wsb_automation_job_status NOT NULL DEFAULT 'QUEUED',attempt_count integer NOT NULL DEFAULT 0,payload jsonb NOT NULL DEFAULT '{}'::jsonb,last_error text,claimed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,dedupe_key),FOREIGN KEY(tenant_id,rule_id) REFERENCES automation_rules(tenant_id,id) ON DELETE SET NULL,FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id) ON DELETE CASCADE);
CREATE INDEX automation_jobs_due_idx ON automation_jobs(status,available_at,due_at);
CREATE TABLE automation_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,job_id uuid,rule_id uuid,event_type text NOT NULL,detail jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(job_id) REFERENCES automation_jobs(id) ON DELETE CASCADE);
CREATE INDEX automation_audit_tenant_time_idx ON automation_audit(tenant_id,created_at DESC);
